{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#7dd3fc;--muted:#cbd5e1}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--muted);background:radial-gradient(1200px 600px at 10% 10%, rgba(34,197,94,0.03), transparent),url('assets/img/pattern.svg');background-color:var(--bg);-webkit-font-smoothing:antialiased}
    header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid rgba(255,255,255,0.03);position:sticky;top:0}
    .nav{display:flex;gap:18px;align-items:center;padding:18px 28px}
    .brand{font-weight:600;color:#fff}
    .nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    .nav a:hover{background:rgba(255,255,255,0.02);color:var(--accent)}
    main{max-width:980px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:28px;border-radius:14px;border:1px solid rgba(255,255,255,0.04)}
    h1{color:#fff;margin:0 0 6px;font-size:22px}
    p.lead{margin:0;color:var(--muted);line-height:1.5}
    .plans{display:flex;gap:16px;margin-top:18px;flex-wrap:wrap}
    .card{flex:1 1 260px;background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .price{font-size:20px;color:#fff;margin:10px 0}
    .features{font-size:14px;color:var(--muted);line-height:1.5}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#002;} 
    .note{font-size:13px;color:var(--muted);margin-top:12px}
    .small{font-size:13px;color:var(--muted)}
    footer{margin:36px 0 120px;color:var(--muted);font-size:13px}
    .mood{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
    .mood button{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:8px 10px;border-radius:999px}
    .mood button.active{background:rgba(125,211,252,0.12);border-color:rgba(125,211,252,0.2);color:var(--accent)}
    @media(max-width:560px){.plans{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <nav class="nav" aria-label="Primary">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <a href="index.html">Start</a>
      <a href="specialties.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <section class="hero" aria-labelledby="rates-heading">
      <div>
        <h1 id="rates-heading">Practical options for regular and short-term support</h1>
        <p class="lead">I offer ongoing membership-style support and smaller, time-limited packages. Pick the structure that fits the kind of work you want: steady presence or a focused series to address a specific question.</p>
        <div class="mood" aria-hidden="false" id="moodBtns">
          <button data-mood="overwhelmed">Overwhelmed</button>
          <button data-mood="stuck">Stuck in a pattern</button>
          <button data-mood="transition">Transitioning</button>
          <button data-mood="focus">Seeking focus</button>
        </div>
      </div>
      <div>
        <div class="plans" id="plans">
          <div class="card" data-plan="ongoing">
            <strong>Ongoing Support Plan</strong>
            <div class="price">$160 / session (monthly membership)</div>
            <div class="features">Regular weekly or biweekly sessions, flexible scheduling, priority booking window, and check-ins via secure messaging between sessions.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Join the Plan</a>
            <div class="note">Membership billed monthly. Cancel any time with 30 days' notice. Not a crisis service.</div>
          </div>
          <div class="card" data-plan="series">
            <strong>Focused Series — 4 sessions</strong>
            <div class="price">$600 for four 50-minute sessions</div>
            <div class="features">A contained series for a defined question or skill practice. Scheduled over 4–8 weeks depending on need.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a Series</a>
            <div class="note">Intended for time-limited goals; may be followed by transitioning to the ongoing plan.</div>
          </div>
          <div class="card" data-plan="single">
            <strong>Single Sessions</strong>
            <div class="price">$190 for a one-time 50-minute session</div>
            <div class="features">Good for check-ins, information-gathering, or to get a sense of the work. No obligation to continue.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Book a Session</a>
            <div class="note">Single sessions available as scheduling permits. Sliding scale considered case-by-case.</div>
          </div>
        </div>
      </div>
      <div style="grid-column:1/-1;margin-top:8px" class="small">If finances are a barrier, please mention this when you contact me; I offer occasional reduced-rate openings. Sessions are confidential within legal limits; see the FAQ for more on boundaries and crisis guidance.</div>
    </section>
    <section style="margin-top:18px" class="hero">
      <h2 style="color:#fff;margin:0 0 8px">How I think about pricing</h2>
      <p class="lead">I aim to make decisions about care straightforward: membership supports ongoing, skills-focused work and continuity; series packages give a clear container for concentrated effort; single sessions are available when you need a one-off appointment. There are no promises of specific outcomes — therapy is collaborative and depends on many factors.</p>
    </section>
    <footer>
      <div>Questions? Call <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a>.</div>
      <div style="margin-top:8px">Office located in {{CITY}}, {{STATE}}. All care follows professional confidentiality with limits (detailed in FAQ).</div>
    </footer>
  </main>
  <script>
    (function(){
      const moodBtns=document.getElementById('moodBtns');
      const planCards=document.querySelectorAll('.card');
      const accent='var(--accent)';
      moodBtns.addEventListener('click',e=>{
        if(e.target.tagName!=='BUTTON')return;
        document.querySelectorAll('#moodBtns button').forEach(b=>b.classList.remove('active'));
        e.target.classList.add('active');
        const mood=e.target.dataset.mood;
        // simple mapping
        const map={overwhelmed:'ongoing',stuck:'series',transition:'ongoing',focus:'series'};
        const match=map[mood]||'single';
        planCards.forEach(card=>{
          if(card.dataset.plan===match){
            card.style.borderColor='rgba(125,211,252,0.25)';
            card.style.boxShadow='0 8px 20px rgba(2,6,23,0.6)';
          }else{card.style.borderColor='rgba(255,255,255,0.03)';card.style.boxShadow='none';}
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071026;--card:rgba(255,255,255,0.04);--muted:#cbd5e1;--accent:#60a5fa}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:var(--muted);background:linear-gradient(180deg,#041027,#071026),url('assets/img/pattern.svg');-webkit-font-smoothing:antialiased}
    header{padding:20px 28px;border-bottom:1px solid rgba(255,255,255,0.02);backdrop-filter:blur(6px)}
    .brand{color:#fff;font-weight:600}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:900px;margin:30px auto;padding:20px}
    .card{background:var(--card);border-radius:12px;padding:18px;border:1px solid rgba(255,255,255,0.03)}
    h1{color:#fff;margin:0 0 8px}
    .qa{margin-top:12px}
    .q{background:transparent;border:none;width:100%;text-align:left;padding:12px 0;color:#fff;font-size:16px;cursor:pointer}
    .a{padding:0 0 12px 0;color:var(--muted);display:none}
    .a.open{display:block}
    .small{font-size:13px;color:var(--muted)}
    .crisis{margin-top:16px;padding:12px;border-radius:8px;background:linear-gradient(90deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03)}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav aria-label="Breadcrumb">
      <a href="index.html">Start</a>
      <a href="specialties.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>
  <main>
    <section class="card">
      <h1>Frequently asked questions</h1>
      <p class="small">Below are practical answers about sessions, membership, and what confidentiality means in this practice. If your question isn’t listed, please reach out.</p>
      <div class="qa" id="faqList">
        <div>
          <button class="q" data-id="one">What kinds of services do you offer?</button>
          <div class="a" id="one">I offer ongoing supportive membership work, short focused series (4 sessions), and single sessions. We’ll choose a format that matches your goals and life demands; the structure is part of the clinical plan rather than a rigid promise.</div>
        </div>
        <div>
          <button class="q" data-id="two">How does the membership work?</button>
          <div class="a" id="two">Membership is a monthly arrangement for regular sessions and continuity of care. It includes priority scheduling, periodic brief check-ins, and the chance to build skills over time. Billing is monthly; you may transition out with 30 days’ notice. It is not emergency coverage.</div>
        </div>
        <div>
          <button class="q" data-id="three">What is your cancellation policy?</button>
          <div class="a" id="three">Please give at least 48 hours' notice to cancel or reschedule. Late cancellations or missed sessions may be billed at the full session rate, except in cases of emergency or unexpected hardship where we can discuss accommodations.</div>
        </div>
        <div>
          <button class="q" data-id="four">How private are sessions?</button>
          <div class="a" id="four">Sessions are confidential. Information is not shared outside this practice without your permission except in the limited situations required by law: when there is an immediate risk of serious harm to yourself or others, suspected abuse of a child or vulnerable adult, or when ordered by a court. If such limits apply, I will tell you as soon as possible.</div>
        </div>
        <div>
          <button class="q" data-id="five">Do you accept insurance?</button>
          <div class="a" id="five">I do not bill insurance directly. I can provide documentation (a super-bill) you may submit to your insurer for possible reimbursement. Insurance companies may require clinical information as a condition of payment; if you intend to seek reimbursement, we can discuss what that may involve.</div>
        </div>
        <div>
          <button class="q" data-id="six">Are sessions telehealth or in-person?</button>
          <div class="a" id="six">I offer telehealth sessions and limited in-person availability. We'll choose what works best for clinical needs and your comfort. Telehealth is not available for crisis situations; see crisis guidance below.</div>
        </div>
      </div>
      <div style="margin-top:14px" class="small">If a question touches on legal, medical, or urgent safety issues, we’ll discuss appropriate referrals and supports; I do not provide emergency services.</div>
    </section>

    <section style="margin-top:18px" class="card" aria-labelledby="boundaries-heading">
      <h2 id="boundaries-heading">Session boundaries, confidentiality, and scope</h2>
      <p class="small">Below is a concise outline of practice boundaries. These are shared to set clear expectations about what care here includes and does not include.</p>
      <button class="q" data-id="bound1">Confidentiality and its limits</button>
      <div class="a" id="bound1">I keep therapy records secure and private. Exceptions include: imminent risk of serious harm, suspected abuse, court orders, or other legal obligations. If release of information is requested, I will explain what is being disclosed and why.</div>
      <button class="q" data-id="bound2">Availability and emergencies</button>
      <div class="a" id="bound2">This practice is not a crisis line. I am available by scheduled appointment and respond to messages during regular hours. If you are in crisis or at immediate risk, contact local emergency services or a crisis hotline (see below). We can discuss emergency planning in a session.</div>
      <button class="q" data-id="bound3">Record keeping and insurance</button>
      <div class="a" id="bound3">I maintain clinical notes to support safe, effective care. If you use insurance, documentation about diagnosis and treatment may be required; I will review that process with you before submitting records.</div>
      <div class="crisis" role="alert">
        <strong style="color:#fff">If you are in immediate danger or at risk of harming yourself or others:</strong>
        <div class="small">Call your local emergency number right away or go to the nearest emergency department. For non-urgent but pressing concerns, you may call your local crisis line. If you are in the United States you can call or text 988 for the Suicide & Crisis Lifeline; if you are elsewhere, contact your local emergency resources.</div>
      </div>
    </section>

    <footer style="margin-top:18px;color:var(--muted)">
      <div>Contact: <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> • Phone: <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a></div>
      <div style="margin-top:6px">Office: {{CITY}}, {{STATE}}. For anything urgent, please use emergency services rather than email or messaging.</div>
    </footer>
  </main>
  <script>
    (function(){
      const buttons=document.querySelectorAll('.q');
      buttons.forEach(btn=>btn.addEventListener('click',()=>{
        const id=btn.dataset.id;
        const panel=document.getElementById(id);
        if(!panel)return;
        panel.classList.toggle('open');
        // simple announce
        btn.setAttribute('aria-expanded',panel.classList.contains('open'));
      }));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071026;--glass:rgba(255,255,255,0.04);--muted:#cbd5e1;--accent:#8b5cf6}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:var(--muted);background:linear-gradient(180deg,#031025,#071026),url('assets/img/pattern.svg')}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-bottom:1px solid rgba(255,255,255,0.02)}
    .brand{color:#fff;font-weight:600}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:840px;margin:28px auto;padding:20px}
    .panel{background:var(--glass);border-radius:12px;padding:18px;border:1px solid rgba(255,255,255,0.03)}
    h1{color:#fff;margin:0 0 8px}
    .muted{color:var(--muted);font-size:15px}
    form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}
    label{font-size:13px;color:var(--muted)}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)}
    .full{grid-column:1/-1}
    .cta{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:none;cursor:pointer}
    .moodRow{display:flex;gap:8px;margin-top:12px}
    .moodRow button{padding:8px 10px;border-radius:999px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted);cursor:pointer}
    .moodRow button.active{background:rgba(139,92,246,0.12);border-color:rgba(139,92,246,0.18);color:var(--accent)}
    .recommend{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(90deg,rgba(255,255,255,0.01),transparent);border:1px solid rgba(255,255,255,0.02);color:var(--muted)}
    .accordion{margin-top:14px}
    .q{display:block;background:none;border:none;color:var(--muted);padding:10px 0;text-align:left;width:100%;cursor:pointer}
    .a{display:none;color:var(--muted);padding-bottom:8px}
    .a.open{display:block}
    .crisis{margin-top:14px;padding:12px;border-radius:8px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
    @media(max-width:720px){form{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav aria-label="Primary">
      <a href="index.html">Start</a>
      <a href="specialties.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>
  <main>
    <section class="panel" aria-labelledby="reserve-heading">
      <h1 id="reserve-heading">Reserve a time</h1>
      <p class="muted">Use the selector below to describe how you’re feeling right now. The recommendation will adjust, and the primary action will update accordingly. This is to help match approach to what matters in the moment.</p>

      <div class="moodRow" role="tablist" aria-label="Mood to method" id="moodCtl">
        <button data-mood="overwhelmed">Overwhelmed</button>
        <button data-mood="sad">Low or sad</button>
        <button data-mood="uncertain">Facing a decision</button>
        <button data-mood="practice">Skill practice</button>
      </div>

      <div class="recommend" id="recommend">Choose a mood to see a recommendation.</div>

      <form id="bookingForm" onsubmit="return false;">
        <label class="full">Full name<input name="name" required></label>
        <label>Email<input name="email" type="email" required></label>
        <label>Phone<input name="phone" type="tel"></label>
        <label>Preferred days/times<textarea name="times" rows="3"></textarea></label>
        <label>Preferred format<select name="format"><option>Telehealth</option><option>In-person</option></select></label>
        <label class="full">Notes for the first session<textarea name="notes" rows="4"></textarea></label>
        <div class="full" style="display:flex;gap:8px;align-items:center">
          <button id="primaryCta" class="cta">{{PRIMARY_CTA_LABEL}}</button>
          <div class="small muted">You will receive a confirmation email with next steps. This site is not an emergency contact point.</div>
        </div>
      </form>

      <div class="accordion" aria-labelledby="boundaries">
        <h3 id="boundaries" style="color:#fff">Session boundaries & confidentiality</h3>
        <button class="q" data-id="c1">What information is kept in records?</button>
        <div class="a" id="c1">I keep brief clinical notes to support care: session themes, treatment focus, and practical plans. Notes are stored securely. If you request copies or a transfer, we’ll discuss the process and any implications.</div>
        <button class="q" data-id="c2">When might confidentiality be broken?</button>
        <div class="a" id="c2">I will keep what we discuss private except for specific legal or safety limits: imminent danger to self or others, suspected abuse of a minor or vulnerable adult, or a court order. I will communicate with you when possible before disclosing information.</div>
        <button class="q" data-id="c3">Is this a crisis service?</button>
        <div class="a" id="c3">No. If you are in immediate danger, please call emergency services or go to the nearest emergency department. For urgent emotional distress, use your local crisis line; in the U.S. call or text 988.</div>
      </div>

      <div class="crisis" role="alert">
        <strong style="color:#fff">Respectful crisis note:</strong>
        <div class="muted">If you are actively suicidal, plan to hurt someone, or are otherwise in immediate danger, call emergency services right away. For non-immediate distress, crisis hotlines can provide immediate support while you arrange care.</div>
      </div>

    </section>
  </main>
  <script>
    (function(){
      const moodCtl=document.getElementById('moodCtl');
      const buttons=[...moodCtl.querySelectorAll('button')];
      const recommend=document.getElementById('recommend');
      const primaryCta=document.getElementById('primaryCta');
      const mapping={
        overwhelmed:{method:'Short-term stabilization',cta:'Request a Stabilization Visit',url:'{{PRIMARY_CTA_URL}}?mode=stabilize'},
        sad:{method:'Regular supportive sessions',cta:'Request Ongoing Care',url:'{{PRIMARY_CTA_URL}}?mode=ongoing'},
        uncertain:{method:'Four-session exploration',cta:'Start a 4-Session Series',url:'{{PRIMARY_CTA_URL}}?mode=series'},
        practice:{method:'Skills-focused packet',cta:'Book a Skills Session',url:'{{PRIMARY_CTA_URL}}?mode=skills'}
      };

      buttons.forEach(b=>b.addEventListener('click',()=>{
        buttons.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        const mood=b.dataset.mood;
        const pick=mapping[mood];
        if(pick){
          recommend.innerHTML='<strong style="color:#fff">Recommendation:</strong> '+pick.method+' — a good fit given how you describe feeling.';
          primaryCta.textContent=pick.cta;
          primaryCta.onclick=(e)=>{e.preventDefault();location.href=pick.url};
        }
      }));

      // accordion
      document.querySelectorAll('.q').forEach(btn=>btn.addEventListener('click',()=>{
        const id=btn.dataset.id;const p=document.getElementById(id);
        p.classList.toggle('open');btn.setAttribute('aria-expanded',p.classList.contains('open'));
      }));

      // fall back: primary cta submits the form locally
      primaryCta.addEventListener('click',function(e){
        e.preventDefault();
        // basic validation
        const form=document.getElementById('bookingForm');
        const name=form.name.value.trim(), email=form.email.value.trim();
        if(!name || !email){alert('Please provide your name and email before continuing.');return;} 
        // simulate send
        alert('Thanks — a message will be sent to '+email+' with next steps.');
      });
    })();
  </script>
</body>
</html>"} 
